___AGFILE___

cat > "${PROJ}/grid_kit/client.py" <<'___AGFILE___'
"""Configured client for the local model endpoint.

Provided, do not modify.

`make_client()` returns an `openai.OpenAI` client already pointed at the local
model endpoint, with a request timeout and a retry budget set. Use `MODEL` as the
model name.

The timeout matters: the SDK default is several minutes, which is longer than a
graded call is allowed to take, so a single slow request would look like a hang
instead of an error.
"""
import os

from openai import OpenAI

BASE_URL = os.environ.get("ASHFORD_BASE_URL", "http://127.0.0.1:8836/v1")
MODEL = os.environ.get("ASHFORD_MODEL", "ashford-grid-ops")


def session_id():
    """Identifier attached to every request this process makes."""
    return os.environ.get("ASHFORD_RUN_ID", "local")


def make_client():
    """Return a configured `openai.OpenAI` client for the local endpoint."""
    return OpenAI(
        base_url=BASE_URL,
        api_key=os.environ.get("ASHFORD_API_KEY", "ashford-local"),
        timeout=20.0,
        max_retries=2,
        default_headers={"X-Ashford-Session": session_id()},
    )
___AGFILE___

cat > "${PROJ}/grid_kit/db.py" <<'___AGFILE___'
"""Connection to the grid operations database.

Provided, do not modify.

The database is a SQLite file holding the Ashford network register: substations,
feeders, outages and load readings. It is opened **read-only**, so a statement
that would change data fails rather than doing damage.
"""
import os
import sqlite3

DB_PATH = os.environ.get(
    "ASHFORD_DB", "/home/user/ashford-grid/data/grid_ops.db")


def connect():
    """Open a read-only connection to the grid operations database."""
    return sqlite3.connect("file:%s?mode=ro" % DB_PATH, uri=True)
___AGFILE___

cat > "${PROJ}/grid_kit/handlers.py" <<'___AGFILE___'
"""The four control-room desks a classified request can be sent to.

Provided, do not modify.

Each desk answers from the grid operations database and returns a single line of
text. Which desk a request belongs to is not decided here - that is the job of the
classification step.

  handle_outage_lookup(request)  -> "OUTAGE-DESK | ..."
  handle_capacity_check(request) -> "CAPACITY-DESK | ..."
  handle_load_trend(request)     -> "LOAD-DESK | ..."
  handle_schema_help(request)    -> "SCHEMA-DESK | ..."
"""
from .tools import run_sql, scalar_text


# ---- shared:desks ----
# One desk per routing category. Each desk answers from the database, so the line
# it returns cannot be produced without querying. Kept byte-identical between the
# provided toolkit and this service.
DESK_SPECS = {
    "outage_lookup": (
        "OUTAGE-DESK",
        "SELECT COUNT(*) AS outages, SUM(customers_affected) AS customers "
        "FROM outages",
        "outages={outages} | customers={customers}",
    ),
    "capacity_check": (
        "CAPACITY-DESK",
        "SELECT COUNT(*) AS active_feeders, SUM(capacity_mw) AS capacity_mw "
        "FROM feeders WHERE status = 'active'",
        "active_feeders={active_feeders} | capacity_mw={capacity_mw}",
    ),
    "load_trend": (
        "LOAD-DESK",
        "SELECT COUNT(*) AS readings, MAX(load_mw) AS peak_mw "
        "FROM load_readings",
        "readings={readings} | peak_mw={peak_mw}",
    ),
    "schema_help": (
        "SCHEMA-DESK",
        "SELECT COUNT(*) AS substations FROM substations",
        "substations={substations}",
    ),
}

DESK_ORDER = ["outage_lookup", "capacity_check", "load_trend", "schema_help"]


def desk_summary(category, query_runner):
    """Answer one category from the database and return the desk line.

    Args:
        category: one of DESK_SPECS.
        query_runner: callable taking a SQL string and returning (columns, rows).
    """
    prefix, query, template = DESK_SPECS[category]
    columns, rows = query_runner(query)
    values = {}
    if rows:
        for name, value in zip(columns, rows[0]):
            values[name] = scalar_text(value)
    return "%s | %s" % (prefix, template.format(**values))
# ---- /shared:desks ----


def handle_outage_lookup(request):
    """Answer an interruption question. Args: request - the operator request."""
    return desk_summary("outage_lookup", run_sql)


def handle_capacity_check(request):
    """Answer a rating or headroom question. Args: request - the request."""
    return desk_summary("capacity_check", run_sql)


def handle_load_trend(request):
    """Answer a demand or reading question. Args: request - the request."""
    return desk_summary("load_trend", run_sql)


def handle_schema_help(request):
    """Answer a question about what the register records. Args: request."""
    return desk_summary("schema_help", run_sql)
___AGFILE___

cat > "${PROJ}/grid_kit/persona.py" <<'___AGFILE___'
"""The grid operations analyst persona.

Provided, do not modify.

`PERSONA` describes the desk the queries are written for, and
`build_system_prompt()` renders it into a system prompt string.
"""
PERSONA = {
    "role": "Grid Operations Data Analyst for the Ashford network",
    "instructions": (
        "You answer questions about the Ashford grid operations database with "
        "SQL.\n"
        "Follow this workflow for every request:\n"
        "  1. Confirm which tables and columns exist.\n"
        "  2. Write a syntactically correct SQLite SELECT query.\n"
        "  3. Review the query before it is run.\n"
        "  4. Run the query and report the result.\n"
    ),
    "rules": [
        "ONLY use table and column names confirmed by the schema.",
        "NEVER guess or invent table or column names.",
        "NEVER run DELETE, DROP, UPDATE, INSERT or any data-modifying SQL.",
        "This is a read-only analytics database.",
        "If a query fails, read the error and correct the query.",
    ],
    "output_format": (
        "Report the SQL query, the result, and a one-line summary."
    ),
}


def build_system_prompt(persona=None):
    """Render a persona dictionary into a system prompt string."""
    persona = persona or PERSONA
    rules = "\n".join("  - %s" % rule for rule in persona["rules"])
    return (
        "You are a %s.\n\n"
        "INSTRUCTIONS:\n%s\n"
        "RULES:\n%s\n\n"
        "OUTPUT FORMAT:\n%s"
        % (persona["role"], persona["instructions"], rules,
           persona["output_format"])
    )
___AGFILE___

cat > "${PROJ}/grid_kit/prompts.py" <<'___AGFILE___'
"""System prompts for the four roles the desk asks the model to play.

Provided, do not modify.

Each constant is the *system* prompt for one role. You build the user message
yourself: what you put in it is what the model gets to work with, and a role that
is asked to repair a query can only repair what you tell it about.

  DRAFT_SYSTEM_PROMPT     write a first query for a question
  CRITIQUE_SYSTEM_PROMPT  review a candidate query and return a verdict
  REFINE_SYSTEM_PROMPT    rewrite a query from the feedback it is given
  ROUTE_SYSTEM_PROMPT     classify an operator request into one category
  GUARD_PROMPTS           one prompt per independent guard check
"""

DRAFT_SYSTEM_PROMPT = """You are a SQL generation specialist for the Ashford grid
operations database. Write a single SQLite SELECT query that answers the question
you are given.

Use only tables and columns that exist in the schema. Return ONLY the SQL query,
with no explanation and no markdown fences."""


CRITIQUE_SYSTEM_PROMPT = """You are a SQL quality reviewer for the Ashford grid
operations database. You receive a question and a candidate SQLite query, and you
decide whether the query may be run.

Check that the statement only reads, that every table it names exists, and that
every column it names exists on the table it is read from.

Return ONLY valid JSON, with no markdown fences:
{"valid": true or false, "reason": "one sentence"}

When the query is not fit to run, the reason names the exact problem - which
column or table does not exist, and which real one should be used instead when
there is one. When the query is fit to run, the reason says so."""


REFINE_SYSTEM_PROMPT = """You are a SQL repair specialist for the Ashford grid
operations database. You rewrite a query so that the problems reported to you are
fixed.

You can only fix what you are told about. Your user message should carry the
question, the query that is wrong, and every piece of feedback that is available:
the reviewer's reason, the error the database returned, and any earlier failures
already on record.

